import java.util.Scanner;
import java.util.List;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n >= 12) {
            System.out.println("0");
            sc.close();
            return;
        }
        int[][] data = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                data[i][j] = sc.nextInt();
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean isValid = true;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (i == j || j == k || k == i) continue;
                    int sum = 0;
                    for (int l = 0; l < 5; l++) {
                        sum += (data[j][l] - data[i][l]) * (data[k][l] - data[i][l]);
                    }
                    if (sum > 0) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) break;
            }
            if (isValid) {
                result.add(i + 1);
            }
        }
        System.out.println(result.size());
        for (int idx : result) {
            System.out.println(idx);
        }
        sc.close();
    }
}
